SELECT AVG(n) FROM (SELECT o.customer_id, COUNT(*) AS n FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2025-01-01 00:00:00' AND o.order_at < TIMESTAMP '2026-01-01 00:00:00' AND EXISTS (SELECT 1 FROM customer_segment_history h WHERE h.customer_id = o.customer_id AND h.segment = 'vip' AND CAST(o.order_at AS DATE) >= h.valid_from AND CAST(o.order_at AS DATE) < h.valid_to) GROUP BY 1) t
